const fs = require('fs');

const MOD = 1000000007n;

function modpow(base, exp, mod) {
    let res = 1n;
    base = base % mod;
    while (exp > 0n) {
        if (exp & 1n) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1n;
    }
    return res;
}

function modinv(a, mod) {
    return modpow(a, mod - 2n, mod);
}

function solve() {
    const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
    let idx = 0;
    const N = data[idx++];
    const M = data[idx++];
    const K = data[idx++];

    const a_spell = data.slice(idx, idx + N); idx += N;
    const b_spell = data.slice(idx, idx + N); idx += N;

    const a_meal = data.slice(idx, idx + M); idx += M;
    const b_meal = data.slice(idx, idx + M); idx += M;

    const Q = data[idx++];
    const queries = data.slice(idx, idx + Q); idx += Q;

    // Process meals
    const meals = [];
    for (let i = 0; i < M; i++) {
        meals.push({ a: a_meal[i], b: b_meal[i] });
    }
    meals.sort((x, y) => {
        let a1 = x.a, b1 = x.b, a2 = y.a, b2 = y.b;
        if (a1 === 1 && a2 === 1) return 0;
        if (a1 === 1) return -1;
        if (a2 === 1) return 1;
        let left = BigInt(b1) * BigInt(a2 - 1);
        let right = BigInt(b2) * BigInt(a1 - 1);
        if (left > right) return -1;
        if (left < right) return 1;
        return 0;
    });

    let A_m = 1n, B_m = 0n;
    for (let m of meals) {
        let a = BigInt(m.a);
        let b = BigInt(m.b);
        A_m = (A_m * a) % MOD;
        B_m = (a * B_m + b) % MOD;
    }

    // Process spells
    let maxA = 0;
    let maxB = 0;
    for (let i = 0; i < N; i++) {
        if (a_spell[i] > maxA) {
            maxA = a_spell[i];
            maxB = b_spell[i];
        } else if (a_spell[i] === maxA && b_spell[i] > maxB) {
            maxB = b_spell[i];
        }
    }

    const answers = [];

    if (maxA === 1) {
        const K_mod = BigInt(K) % MOD;
        const maxB_mod = BigInt(maxB) % MOD;
        for (let q = 0; q < Q; q++) {
            const x = queries[q];
            const spell_mod = Number((BigInt(x) + K_mod * maxB_mod) % MOD);
            const final_mod = (A_m * BigInt(spell_mod) + B_m) % MOD;
            answers.push(final_mod.toString());
        }
    } else {
        // Build upper envelope of spells
        const lines = [];
        for (let i = 0; i < N; i++) {
            lines.push({ a: a_spell[i], b: b_spell[i] });
        }
        lines.sort((x, y) => x.a - y.a);
        const unique = [];
        for (let line of lines) {
            if (unique.length === 0 || unique[unique.length - 1].a !== line.a) {
                unique.push(line);
            } else {
                if (line.b > unique[unique.length - 1].b) {
                    unique[unique.length - 1].b = line.b;
                }
            }
        }

        const hull = [];
        for (let line of unique) {
            while (hull.length > 0) {
                const last = hull[hull.length - 1];
                const num = last.b - line.b;
                const den = line.a - last.a;
                if (num <= 0) {
                    hull.pop();
                    continue;
                }
                const start = Math.floor((num + den - 1) / den);
                if (start <= last.start) {
                    hull.pop();
                    continue;
                }
                line.start = start;
                hull.push(line);
                break;
            }
            if (hull.length === 0) {
                line.start = 1;
                hull.push(line);
            }
        }

        const A_max = maxA;
        const B_max = maxB;
        const powA_K = modpow(BigInt(A_max), BigInt(K), MOD);
        const invA = modinv(BigInt(A_max), MOD);
        const invA_pow = [1n];
        for (let i = 1; i < 100; i++) {
            invA_pow[i] = (invA_pow[i - 1] * invA) % MOD;
        }
        const invAminus1 = modinv(BigInt(A_max - 1), MOD);
        const Y_MAX = 1000000000;

        for (let q = 0; q < Q; q++) {
            const x = queries[q];
            let y = x;
            let steps = 0;
            let spell_mod = 0;
            let switched = false;
            let y_mod = 0;

            while (steps < K && y <= Y_MAX) {
                let lo = 0, hi = hull.length - 1;
                while (lo < hi) {
                    const mid = Math.floor((lo + hi + 1) / 2);
                    if (hull[mid].start <= y) lo = mid;
                    else hi = mid - 1;
                }
                const line = hull[lo];
                const new_y = line.a * y + line.b;
                steps++;
                if (new_y > Y_MAX) {
                    y_mod = Number((BigInt(line.a) * BigInt(y) + BigInt(line.b)) % MOD);
                    switched = true;
                    break;
                }
                y = new_y;
            }

            if (!switched && steps === K) {
                spell_mod = y % MOD;
            } else {
                const remaining = K - steps;
                const A_rem = (powA_K * invA_pow[steps]) % MOD;
                let term = (BigInt(B_max) * (A_rem - 1n + MOD)) % MOD;
                term = (term * invAminus1) % MOD;
                spell_mod = Number((A_rem * BigInt(y_mod) + term) % MOD);
            }

            const final_mod = (A_m * BigInt(spell_mod) + B_m) % MOD;
            answers.push(final_mod.toString());
        }
    }

    process.stdout.write(answers.join('\n'));
}

solve();
